    private static void remapLegacyMoltenFluids(MissingMappingsEvent event) {
        event.getMappings(Registries.FLUID, GTCEu.MOD_ID).forEach(mapping -> {
            String path = mapping.getKey().getPath();
            boolean flowing = path.startsWith("flowing_");
            String materialName = legacyMoltenMaterial(flowing ? path.substring("flowing_".length()) : path);
            if (materialName == null) return;
            var liquid = GTMaterials.get(materialName).getFluid(FluidStorageKeys.LIQUID);
            if (flowing && liquid instanceof FlowingFluid fluid) {
                mapping.remap(fluid.getFlowing());
            } else if (!flowing && liquid != null) {
                mapping.remap(liquid);
            } else {
                mapping.warn();
            }
        });
        event.getMappings(Registries.ITEM, GTCEu.MOD_ID).forEach(mapping -> {
            String path = mapping.getKey().getPath();
            if (!path.endsWith("_bucket")) return;
            String materialName = legacyMoltenMaterial(path.substring(0, path.length() - "_bucket".length()));
            if (materialName == null) return;
            var liquid = GTMaterials.get(materialName).getFluid(FluidStorageKeys.LIQUID);
            if (liquid != null && liquid.getBucket() != Items.AIR) {
                mapping.remap(liquid.getBucket());
            } else {
                mapping.warn();
            }
        });
        event.getMappings(ForgeRegistries.Keys.FLUID_TYPES, GTCEu.MOD_ID).forEach(mapping -> {
            String materialName = legacyMoltenMaterial(mapping.getKey().getPath());
            if (materialName == null) return;
            var liquid = GTMaterials.get(materialName).getFluid(FluidStorageKeys.LIQUID);
            if (liquid != null) mapping.remap(liquid.getFluidType());
            else mapping.warn();
        });
        // We never defined placable moltens, no need to handle them!
    }

    private static String legacyMoltenMaterial(String path) {
        if (!path.startsWith("molten_")) return null;
        String materialName = path.substring("molten_".length());
        return LEGACY_MOLTEN_MATERIALS.contains(materialName) ? materialName : null;
    }

    @SubscribeEvent
    public static void remapIds(MissingMappingsEvent event) {
        remapLegacyMoltenFluids(event);
        event.getMappings(Registries.BLOCK, GTCEu.MOD_ID).forEach(mapping -> {
            if (mapping.getKey().equals(GTCEu.id("tungstensteel_coil_block"))) {
                mapping.remap(GTBlocks.COIL_RTMALLOY.get());
            }
            if (mapping.getKey().equals(GTCEu.id("steam_miner"))) {
                mapping.remap(GTMachines.STEAM_MINER.first().getBlock());
            }
        });
        event.getMappings(Registries.ITEM, GTCEu.MOD_ID).forEach(mapping -> {
            if (mapping.getKey().equals(GTCEu.id("tungstensteel_coil_block"))) {
                mapping.remap(GTBlocks.COIL_RTMALLOY.get().asItem());
            }
            if (mapping.getKey().equals(GTCEu.id("steam_miner"))) {
                mapping.remap(GTMachines.STEAM_MINER.first().getItem());
            }
            if (mapping.getKey().equals(GTCEu.id("tungstensteel_fluid_cell"))) {
                mapping.remap(GTItems.FLUID_CELL_LARGE_TUNGSTEN_STEEL.get().asItem());
            }
            if (mapping.getKey().equals(GTCEu.id("avanced_nanomuscle_chestplate"))) {
                mapping.remap(GTItems.NANO_CHESTPLATE_ADVANCED.get());
            }
            String path = mapping.getKey().getPath();
            if (path.matches("[lhi]v_.+_wirecutter")) {
                String suffix = "_wirecutter";
                String typeString = path.substring(0, 2) + suffix; // [lhi]v_wirecutter -- tooltype name
                String matString = path.substring(3, path.length() - suffix.length()); // material name

                GTToolType type = GTToolType.getTypes().get(typeString);
                Material material = GTMaterials.get(matString);
                if (type == null || material == null) {
                    mapping.warn();
                    return;
                }
                var tool = GTMaterialItems.TOOL_ITEMS.get(material, type);
                if (tool == null) {
                    mapping.warn();
                    return;
                }
                mapping.remap(tool.asItem());
            }
        });
        event.getMappings(Registries.BLOCK_ENTITY_TYPE, GTCEu.MOD_ID).forEach(mapping -> {
            if (mapping.getKey().equals(GTCEu.id("steam_miner"))) {
                mapping.remap(GTMachines.STEAM_MINER.first().getBlockEntityType());
            }
        });

        event.getMappings(Registries.BLOCK, "gregiceng").forEach(mapping -> {
            String path = mapping.getKey().getPath();
            switch (path) {
                case "stocking_bus", "adv_stocking_bus" -> mapping
                        .remap(GTAEMachines.STOCKING_IMPORT_BUS_ME.getBlock());
                case "stocking_hatch", "adv_stocking_hatch" -> mapping
                        .remap(GTAEMachines.STOCKING_IMPORT_HATCH_ME.getBlock());
                case "crafting_io_buffer" -> mapping.remap(GTAEMachines.ME_PATTERN_BUFFER.getBlock());
                case "crafting_io_slave" -> mapping.remap(GTAEMachines.ME_PATTERN_BUFFER_PROXY.getBlock());
            }
            if (path.contains("input_buffer")) {
                ResourceLocation newName = GTCEu.id(path.replace("input_buffer", "dual_input_hatch"));
                if (mapping.getRegistry().containsKey(newName)) {
                    mapping.remap(mapping.getRegistry().getValue(newName));
                } else {
                    mapping.remap(GTMachines.DUAL_IMPORT_HATCH[GTValues.LuV].getBlock());
                }
            } else if (path.contains("output_buffer")) {
                ResourceLocation newName = GTCEu.id(path.replace("output_buffer", "dual_output_hatch"));
                if (mapping.getRegistry().containsKey(newName)) {
                    mapping.remap(mapping.getRegistry().getValue(newName));
                } else {
                    mapping.remap(GTMachines.DUAL_EXPORT_HATCH[GTValues.LuV].getBlock());
                }
            }
        });
        event.getMappings(Registries.BLOCK_ENTITY_TYPE, "gregiceng").forEach(mapping -> {
            String path = mapping.getKey().getPath();
            switch (path) {
                case "stocking_bus", "adv_stocking_bus" -> mapping
                        .remap(GTAEMachines.STOCKING_IMPORT_BUS_ME.getBlockEntityType());
                case "stocking_hatch", "adv_stocking_hatch" -> mapping
                        .remap(GTAEMachines.STOCKING_IMPORT_HATCH_ME.getBlockEntityType());
                case "crafting_io_buffer" -> mapping.remap(GTAEMachines.ME_PATTERN_BUFFER.getBlockEntityType());
                case "crafting_io_slave" -> mapping.remap(GTAEMachines.ME_PATTERN_BUFFER_PROXY.getBlockEntityType());
            }
            if (path.contains("input_buffer")) {
                ResourceLocation newName = GTCEu.id(path.replace("input_buffer", "dual_input_hatch"));
                if (mapping.getRegistry().containsKey(newName)) {
                    mapping.remap(mapping.getRegistry().getValue(newName));
                } else {
                    mapping.remap(GTMachines.DUAL_IMPORT_HATCH[GTValues.LuV].getBlockEntityType());
                }
            } else if (path.contains("output_buffer")) {
                ResourceLocation newName = GTCEu.id(path.replace("output_buffer", "dual_output_hatch"));
                if (mapping.getRegistry().containsKey(newName)) {
                    mapping.remap(mapping.getRegistry().getValue(newName));
                } else {
                    mapping.remap(GTMachines.DUAL_EXPORT_HATCH[GTValues.LuV].getBlockEntityType());
                }
            }
        });
        event.getMappings(Registries.ITEM, "gregiceng").forEach(mapping -> {
            String path = mapping.getKey().getPath();
            switch (path) {
                case "stocking_bus", "adv_stocking_bus" -> mapping.remap(GTAEMachines.STOCKING_IMPORT_BUS_ME.getItem());
                case "stocking_hatch", "adv_stocking_hatch" -> mapping
                        .remap(GTAEMachines.STOCKING_IMPORT_HATCH_ME.getItem());
                case "crafting_io_buffer" -> mapping.remap(GTAEMachines.ME_PATTERN_BUFFER.getItem());
                case "crafting_io_slave" -> mapping.remap(GTAEMachines.ME_PATTERN_BUFFER_PROXY.getItem());
            }
            if (path.contains("input_buffer")) {
                ResourceLocation newName = GTCEu.id(path.replace("input_buffer", "dual_input_hatch"));
                if (mapping.getRegistry().containsKey(newName)) {
                    mapping.remap(mapping.getRegistry().getValue(newName));
                } else {
                    mapping.remap(GTMachines.DUAL_IMPORT_HATCH[GTValues.LuV].getItem());
                }
            } else if (path.contains("output_buffer")) {
                ResourceLocation newName = GTCEu.id(path.replace("output_buffer", "dual_output_hatch"));
                if (mapping.getRegistry().containsKey(newName)) {
                    mapping.remap(mapping.getRegistry().getValue(newName));
                } else {
                    mapping.remap(GTMachines.DUAL_EXPORT_HATCH[GTValues.LuV].getItem());
                }
            }
        });

        for (TagPrefix prefix : GTRegistries.TAG_PREFIXES) {
            String first = prefix.invertedName ? toLowerCaseUnderscore(prefix.name) : "(.+?)";
            String last = prefix.invertedName ? "(.+?)" : toLowerCaseUnderscore(prefix.name);
            Pattern idPattern = Pattern.compile(first + "_" + last);
            event.getMappings(Registries.BLOCK, GTCEu.MOD_ID).forEach(mapping -> {
                Matcher matcher = idPattern.matcher(mapping.getKey().getPath());
                if (matcher.matches()) {
                    BlockEntry<? extends Block> block = GTMaterialBlocks.MATERIAL_BLOCKS.get(prefix,
                            GTRegistries.MATERIALS.get(GTCEu.id(matcher.group(1))));
                    if (block != null && block.isPresent()) {
                        mapping.remap(block.get());
                    }
                }
            });
            event.getMappings(Registries.ITEM, GTCEu.MOD_ID).forEach(mapping -> {
                Matcher matcher = idPattern.matcher(mapping.getKey().getPath());
                if (matcher.matches()) {
                    Material material = GTRegistries.MATERIALS.get(GTCEu.id(matcher.group(1)));
                    if (material == null) return;
                    BlockEntry<? extends Block> block = GTMaterialBlocks.MATERIAL_BLOCKS.get(prefix, material);
                    if (block != null && block.isPresent()) {
                        mapping.remap(block.asItem());
                    } else {
                        ItemEntry<? extends Item> item = GTMaterialItems.MATERIAL_ITEMS.get(prefix, material);
                        if (item != null && item.isPresent()) mapping.remap(item.asItem());
                    }
                }
            });
        }
    }
}

package com.gregtechceu.gtceu.common.capability;

import com.gregtechceu.gtceu.GTCEu;
import com.gregtechceu.gtceu.api.capability.GTCapabilityHelper;
import com.gregtechceu.gtceu.api.data.chemical.material.properties.HazardProperty;
import com.gregtechceu.gtceu.api.data.medicalcondition.MedicalCondition;
import com.gregtechceu.gtceu.api.registry.GTRegistries;
import com.gregtechceu.gtceu.common.network.GTNetwork;
import com.gregtechceu.gtceu.common.network.packets.hazard.SPacketAddHazardZone;
import com.gregtechceu.gtceu.common.network.packets.hazard.SPacketRemoveHazardZone;
import com.gregtechceu.gtceu.common.network.packets.hazard.SPacketSyncHazardZoneStrength;
import com.gregtechceu.gtceu.config.ConfigHolder;

import net.minecraft.core.BlockPos;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.nbt.ListTag;
import net.minecraft.nbt.NbtUtils;
import net.minecraft.nbt.Tag;
import net.minecraft.network.FriendlyByteBuf;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.level.ChunkPos;
import net.minecraft.world.level.chunk.LevelChunk;
import net.minecraft.world.level.saveddata.SavedData;

import lombok.AllArgsConstructor;
import lombok.Getter;
import lombok.Setter;
import lombok.experimental.Accessors;
import org.jetbrains.annotations.NotNull;
import org.jetbrains.annotations.Nullable;

import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import java.util.stream.Stream;

/**
 * Full-chunk environmental hazards. e.g. pollution.
 */
public class EnvironmentalHazardSavedData extends SavedData {

    public static final float MIN_STRENGTH_FOR_SPREAD = 1000;

    private final ServerLevel serverLevel;

    /**
     * Map of source position to a triple of (trigger, material).
     */
    @Getter
    private final Map<ChunkPos, HazardZone> hazardZones = new HashMap<>();

    public static EnvironmentalHazardSavedData getOrCreate(ServerLevel serverLevel) {
        return serverLevel.getDataStorage().computeIfAbsent(tag -> new EnvironmentalHazardSavedData(serverLevel, tag),
                () -> new EnvironmentalHazardSavedData(serverLevel), "gtceu_environmental_hazard_tracker");
    }

    public EnvironmentalHazardSavedData(ServerLevel serverLevel) {
        this.serverLevel = serverLevel;
    }

    public EnvironmentalHazardSavedData(ServerLevel serverLevel, CompoundTag tag) {
        this(serverLevel);
        if (!ConfigHolder.INSTANCE.gameplay.environmentalHazards) {
            return;
        }

        ListTag allHazardZones = tag.getList("zones", Tag.TAG_COMPOUND);
        for (int i = 0; i < allHazardZones.size(); ++i) {
            CompoundTag zoneTag = allHazardZones.getCompound(i);

            ChunkPos source = new ChunkPos(zoneTag.getLong("pos"));
            HazardZone zone = HazardZone.deserializeNBT(zoneTag);
            if (zone == null) {
                continue;
            }

            this.hazardZones.put(source, zone);
        }
    }

    public void tick() {
        if (!ConfigHolder.INSTANCE.gameplay.environmentalHazards) {
            return;
        }

        Set<ChunkPos> zonesToSpread = new HashSet<>();
        Set<ChunkPos> zonesToRemove = new HashSet<>();
        for (final var entry : hazardZones.entrySet()) {
            HazardZone zone = entry.getValue();
            Stream<ServerPlayer> playersInZone = serverLevel.players()
                    .stream()
                    .filter(player -> new ChunkPos(BlockPos.containing(player.getEyePosition()))
                            .equals(entry.getKey()));
            tickPlayerHazards(zone, playersInZone);

            zone = zone.removeStrength(ConfigHolder.INSTANCE.gameplay.environmentalHazardDecayRate);
            if (zone == null) {
                zonesToRemove.add(entry.getKey());
            } else if (zone.canSpread() && zone.strength() > MIN_STRENGTH_FOR_SPREAD) {
                zonesToSpread.add(entry.getKey());
            }
        }

        // remove empty zones
        for (ChunkPos pos : zonesToRemove) {
            hazardZones.remove(pos);
            if (this.serverLevel.hasChunk(pos.x, pos.z)) {
                LevelChunk chunk = this.serverLevel.getChunk(pos.x, pos.z);
                GTNetwork.sendToAllPlayersTrackingChunk(chunk, new SPacketRemoveHazardZone(pos));
            }
        }

        for (ChunkPos pos : zonesToSpread) {
            final HazardZone zone = hazardZones.get(pos);
            ChunkPos[] relativePositions = new ChunkPos[] {
                    new ChunkPos(pos.x, pos.z - 1),
                    new ChunkPos(pos.x, pos.z + 1),
                    new ChunkPos(pos.x - 1, pos.z),
                    new ChunkPos(pos.x + 1, pos.z)
            };
            float removedStrength = 0;
            for (ChunkPos relativePos : relativePositions) {
                hazardZones.compute(relativePos, (k, v) -> {
                    HazardZone newZone;
                    if (v != null && v.condition() == zone.condition() && v.trigger() == zone.trigger()) {
                        newZone = v.addStrength(20);
                        sendSyncZonePacket(k, newZone);
                    } else {
                        newZone = new HazardZone(k.getMiddleBlockPosition(zone.source().getY()), 20, true,
                                zone.trigger(), zone.condition());
                        sendAddZonePacket(k, newZone);
                    }
                    return newZone;
                });
                removedStrength += 20;
            }
            HazardZone newZone = zone.removeStrength(removedStrength);
            if (newZone == null) {
                hazardZones.remove(pos);
                if (this.serverLevel.hasChunk(pos.x, pos.z)) {
                    LevelChunk chunk = this.serverLevel.getChunk(pos.x, pos.z);
                    GTNetwork.sendToAllPlayersTrackingChunk(chunk, new SPacketRemoveHazardZone(pos));
                }
            }
            this.setDirty();
        }
    }

    public void tickPlayerHazards(final HazardZone zone, Stream<ServerPlayer> playerStream) {
        playerStream.forEach(player -> {
            if (zone.trigger().protectionType().isProtected(player)) {
                // entity has proper safety equipment, so damage it per material every 5 seconds.
                zone.trigger().protectionType().damageEquipment(player, 1);
                // don't progress this material condition if entity is protected
                return;
            }

            MedicalConditionTracker tracker = GTCapabilityHelper.getMedicalConditionTracker(player);
            if (tracker == null) {
                return;
            }
            tracker.progressCondition(zone.condition(), zone.strength() / 1000f);
        });
    }

    /**
     * finds the hazard zone that's in the chunk pos.
     *
     * @param pos the position to find zones for.
     * @return all zones that were found.
     */
    @Nullable
    public HazardZone getZoneByPos(ChunkPos pos) {
        return hazardZones.get(pos);
    }

    /**
     * finds the hazard zone that's in the chunk the block pos is in.
     *
     * @param containedPos the position to find zones for.
     * @return all zones that were found.
     */
    @Nullable
    public HazardZone getZoneByContainedPos(BlockPos containedPos) {
        return getZoneByPos(new ChunkPos(containedPos));
    }

    /**
     * finds all hazard zones that contain the given position and have the correct condition.
     *
     * @param containedPos the position to find zones for.
     * @return all zones that were found.
     */
    @Nullable
    public HazardZone getZoneByContainedPosAndCondition(BlockPos containedPos, MedicalCondition condition) {
        HazardZone zone = hazardZones.get(new ChunkPos(containedPos));
        return zone != null && zone.condition == condition ? zone : null;
    }

    public void removeZone(BlockPos inChunkPos) {
        this.removeZone(new ChunkPos(inChunkPos));
    }

    public void removeZone(BlockPos inChunkPos, MedicalCondition condition) {
        ChunkPos chunkPos = new ChunkPos(inChunkPos);
        if (this.hazardZones.get(chunkPos).condition() == condition) {
            removeZone(chunkPos);
        }
    }

    public void removeZone(ChunkPos chunkPos) {
        this.hazardZones.remove(chunkPos);
        if (this.serverLevel.hasChunk(chunkPos.x, chunkPos.z)) {
            LevelChunk chunk = this.serverLevel.getChunk(chunkPos.x, chunkPos.z);
            GTNetwork.sendToAllPlayersTrackingChunk(chunk, new SPacketRemoveHazardZone(chunkPos));
        }
    }

    public void addZone(ChunkPos source, HazardZone zone) {
        if (!ConfigHolder.INSTANCE.gameplay.environmentalHazards) {
            return;
        }

        HazardZone existing = this.hazardZones.get(source);
        if (existing != null && existing.condition == zone.condition) {
            existing.addStrength(zone.strength());
            sendSyncZonePacket(source, existing);
        } else if (!this.hazardZones.containsKey(source)) {
            this.hazardZones.put(source, zone);
            sendAddZonePacket(source, zone);
        }
        this.setDirty();
    }

    public void addZone(BlockPos source, float strength, boolean canSpread,
                        HazardProperty.HazardTrigger trigger, MedicalCondition condition) {
        addZone(new ChunkPos(source), new HazardZone(source, strength, canSpread, trigger, condition));
    }

    @NotNull
    @Override
    public CompoundTag save(@NotNull CompoundTag compoundTag) {
        ListTag hazardZonesTag = new ListTag();
        for (var entry : hazardZones.entrySet()) {
            CompoundTag zoneTag = new CompoundTag();

            zoneTag.putLong("pos", entry.getKey().toLong());
            entry.getValue().serializeNBT(zoneTag);

            hazardZonesTag.add(zoneTag);
        }
        compoundTag.put("zones", hazardZonesTag);
        return compoundTag;
    }

    @Accessors(fluent = true)
    @AllArgsConstructor
    public static class HazardZone {

        @Getter
        private final BlockPos source;
        @Getter
        @Setter
        private float strength;
        @Getter
        private final boolean canSpread;
        @Getter
        private final HazardProperty.HazardTrigger trigger;
        @Getter
        private final MedicalCondition condition;

        public HazardZone addStrength(float toAdd) {
            this.strength += toAdd;
            return this;
        }

        public HazardZone removeStrength(float toRemove) {
            this.strength -= toRemove;
            if (this.strength <= 0) {
                return null;
            }
            return this;
        }

        public CompoundTag serializeNBT(CompoundTag zoneTag) {
            zoneTag.put("source", NbtUtils.writeBlockPos(source));
            zoneTag.putFloat("strength", strength);
            zoneTag.putBoolean("can_spread", canSpread);
            zoneTag.putString("trigger", trigger.name());
            zoneTag.putString("condition", condition.id.toString());

            return zoneTag;
        }

        public static @Nullable HazardZone deserializeNBT(CompoundTag zoneTag) {
            BlockPos source = NbtUtils.readBlockPos(zoneTag.getCompound("source"));
            float strength = zoneTag.getFloat("strength");
            boolean canSpread = zoneTag.getBoolean("can_spread");
            HazardProperty.HazardTrigger trigger = HazardProperty.HazardTrigger.ALL_TRIGGERS
                    .get(zoneTag.getString("trigger"));
            ResourceLocation id = GTCEu.id(zoneTag.getString("condition"));
            if (!GTRegistries.MEDICAL_CONDITIONS.containsKey(id)) {
                return null;
            }
            MedicalCondition condition = GTRegistries.MEDICAL_CONDITIONS.get(id);

            return new HazardZone(source, strength, canSpread, trigger, condition);
        }

        public void toNetwork(FriendlyByteBuf buf) {
            buf.writeBlockPos(source);
            buf.writeFloat(strength);
            buf.writeBoolean(canSpread);
            buf.writeUtf(trigger.name());
            buf.writeResourceLocation(condition.id);
        }

        public static HazardZone fromNetwork(FriendlyByteBuf buf) {
            BlockPos source = buf.readBlockPos();
            float strength = buf.readFloat();
            boolean canSpread = buf.readBoolean();
            HazardProperty.HazardTrigger trigger = HazardProperty.HazardTrigger.ALL_TRIGGERS.get(buf.readUtf());
            MedicalCondition condition = GTRegistries.MEDICAL_CONDITIONS.get(buf.readResourceLocation());
            return new HazardZone(source, strength, canSpread, trigger, condition);
        }
    }

    public void sendAddZonePacket(ChunkPos pos, HazardZone zone) {
        if (this.serverLevel.hasChunk(pos.x, pos.z)) {
            LevelChunk chunk = this.serverLevel.getChunk(pos.x, pos.z);
            GTNetwork.sendToAllPlayersTrackingChunk(chunk, new SPacketAddHazardZone(pos, zone));
        }
    }

    public void sendSyncZonePacket(ChunkPos pos, HazardZone zone) {
        if (this.serverLevel.hasChunk(pos.x, pos.z)) {
            LevelChunk chunk = this.serverLevel.getChunk(pos.x, pos.z);
            GTNetwork.sendToAllPlayersTrackingChunk(chunk, new SPacketSyncHazardZoneStrength(pos, zone.strength()));
        }
    }
}

package com.gregtechceu.gtceu.common.capability;

import com.gregtechceu.gtceu.GTCEu;
import com.gregtechceu.gtceu.api.GTValues;
import com.gregtechceu.gtceu.api.capability.GTCapabilityHelper;
import com.gregtechceu.gtceu.api.data.chemical.material.properties.HazardProperty;
import com.gregtechceu.gtceu.api.data.medicalcondition.MedicalCondition;
import com.gregtechceu.gtceu.api.registry.GTRegistries;
import com.gregtechceu.gtceu.common.particle.HazardParticleOptions;
import com.gregtechceu.gtceu.config.ConfigHolder;
import com.gregtechceu.gtceu.utils.BreadthFirstBlockSearch;

import net.minecraft.core.BlockPos;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.nbt.ListTag;
import net.minecraft.nbt.NbtUtils;
import net.minecraft.nbt.Tag;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.util.RandomSource;
import net.minecraft.world.level.saveddata.SavedData;

import it.unimi.dsi.fastutil.objects.Object2IntMap;
import it.unimi.dsi.fastutil.objects.Object2IntOpenHashMap;
import lombok.Getter;
import org.jetbrains.annotations.NotNull;
import org.jetbrains.annotations.Nullable;

import java.util.*;
import java.util.stream.Collectors;
import java.util.stream.Stream;

/**
 * localized, block-based environmental hazards. e.g. radiation.
 * do not use for large-scale effects, as this stores all blocks where an effect is, and thus will be too slow for that.
 */
public class LocalizedHazardSavedData extends SavedData {

    public static final int MIN_STRENGTH_FOR_SPREAD = 100;

    private final ServerLevel serverLevel;

    /**
     * Map of source position to a triple of (trigger, material).
     */
    @Getter
    private final Map<BlockPos, HazardZone> hazardZones = new HashMap<>();

    public static LocalizedHazardSavedData getOrCreate(ServerLevel serverLevel) {
        return serverLevel.getDataStorage().computeIfAbsent(tag -> new LocalizedHazardSavedData(serverLevel, tag),
                () -> new LocalizedHazardSavedData(serverLevel), "gtceu_localized_hazard_tracker");
    }

    public LocalizedHazardSavedData(ServerLevel serverLevel) {
        this.serverLevel = serverLevel;
    }

    public LocalizedHazardSavedData(ServerLevel serverLevel, CompoundTag tag) {
        this(serverLevel);
        if (!ConfigHolder.INSTANCE.gameplay.environmentalHazards) {
            return;
        }

        ListTag allHazardZones = tag.getList("zones", Tag.TAG_COMPOUND);
        for (int i = 0; i < allHazardZones.size(); ++i) {
            CompoundTag zoneTag = allHazardZones.getCompound(i);

            BlockPos source = BlockPos.of(zoneTag.getLong("pos"));
            HazardZone zone = HazardZone.deserializeNBT(zoneTag);

            this.hazardZones.put(source, zone);
        }
    }

    public void tick() {
        if (!ConfigHolder.INSTANCE.gameplay.environmentalHazards) {
            return;
        }

        Object2IntMap<BlockPos> zonesToSpread = new Object2IntOpenHashMap<>();

        RandomSource random = serverLevel.random;
        for (final var entry : hazardZones.entrySet()) {
            HazardZone zone = entry.getValue();
            if (zone.strength() < MIN_STRENGTH_FOR_SPREAD / 5) {
                continue;
            }
            // try to spawn particles on every block in the zone if it's loaded and empty.
            for (BlockPos pos : zone.blocks()) {
                if (serverLevel.isLoaded(pos) &&
                        !serverLevel.getBlockState(pos).isCollisionShapeFullBlock(serverLevel, pos) &&
                        GTValues.RNG.nextInt(64000 / zone.strength()) == 0) {
                    serverLevel.sendParticles(
                            new HazardParticleOptions(zone.condition().color, zone.strength() / 250f),
                            pos.getX() + random.nextDouble(), pos.getY() + random.nextDouble(),
                            pos.getZ() + random.nextDouble(),
                            1, 0, 0, 0, 0.1);
                }
            }

            Stream<ServerPlayer> playersInZone = serverLevel.players()
                    .stream()
                    .filter(player -> zone.blocks().contains(BlockPos.containing(player.getEyePosition())));
            tickPlayerHazards(zone, playersInZone);

            if (zone.canSpread() && zone.strength() > MIN_STRENGTH_FOR_SPREAD) {
                zonesToSpread.put(entry.getKey(), (zone.strength() - MIN_STRENGTH_FOR_SPREAD) / 500);
            }
        }

        zonesToSpread.forEach(this::expandHazard);
    }

    public void tickPlayerHazards(final HazardZone zone, Stream<ServerPlayer> playerStream) {
        playerStream.forEach(player -> {
            if (zone.trigger().protectionType().isProtected(player)) {
                // entity has proper safety equipment, so damage it per material every 5 seconds.
                zone.trigger().protectionType().damageEquipment(player, 1);
                // don't progress this material condition if entity is protected
                return;
            }

            MedicalConditionTracker tracker = GTCapabilityHelper.getMedicalConditionTracker(player);
            if (tracker == null) {
                return;
            }
            tracker.progressCondition(zone.condition(), zone.strength() / 1000f);
        });
    }

    /**
     * finds the hazard zone that's in the chunk the block pos is in and has the correct condition.
     *
     * @param containedPos the position to find zones for.
     * @return all zones that were found.
     */
    @Nullable
    public HazardZone getZoneByContainedPos(BlockPos containedPos) {
        for (HazardZone zone : hazardZones.values()) {
            if (zone.blocks().contains(containedPos)) {
                return zone;
            }
        }
        return null;
    }

    /**
     * finds all hazard zones that contain the given position and have the correct condition.
     *
     * @param containedPos the position to find zones for.
     * @return all zones that were found.
     */
    @Nullable
    public HazardZone getZoneByContainedPosAndCondition(BlockPos containedPos, MedicalCondition condition) {
        for (HazardZone zone : hazardZones.values()) {
            if (zone.condition() == condition && zone.blocks().contains(containedPos)) {
                return zone;
            }
        }
        return null;
    }

    public void removeZoneByPosition(BlockPos containedPos) {
        BlockPos toRemove = null;
        for (var entry : hazardZones.entrySet()) {
            if (entry.getValue().blocks().contains(containedPos)) {
                toRemove = entry.getKey();
            }
        }
        hazardZones.remove(toRemove);
    }

    public void removeZoneByPosition(BlockPos containedPos, MedicalCondition condition) {
        BlockPos toRemove = null;
        for (var entry : hazardZones.entrySet()) {
            if (entry.getValue().condition() == condition && entry.getValue().blocks().contains(containedPos)) {
                toRemove = entry.getKey();
            }
        }
        hazardZones.remove(toRemove);
    }

    public boolean expandHazard(BlockPos source, int blocksToAdd) {
        if (!ConfigHolder.INSTANCE.gameplay.environmentalHazards) {
            return true;
        }

        if (blocksToAdd <= 0) {
            return false;
        }
        if (this.hazardZones.containsKey(source)) {
            final HazardZone zone = hazardZones.get(source);

            Set<BlockPos> allValidBlocks = BreadthFirstBlockSearch.search(blockPos -> !zone.blocks().contains(blockPos),
                    source, blocksToAdd);

            for (BlockPos found : allValidBlocks) {
                zone.blocks().add(found);
            }
            this.setDirty();
            return true;
        }
        return false;
    }

    public void addSphericalZone(BlockPos source, int sphereRadius, boolean canSpread,
                                 HazardProperty.HazardTrigger trigger, MedicalCondition condition) {
        if (expandHazard(source, (int) ((4.0 / 3) * Math.PI * Math.pow(sphereRadius, 3) / 50))) {
            return;
        }

        Set<BlockPos> blocks = new HashSet<>();
        for (int x = -sphereRadius; x < sphereRadius; x++) {
            for (int y = -sphereRadius; y < sphereRadius; y++) {
                for (int z = -sphereRadius; z < sphereRadius; z++) {
                    float sizeFractionX = (float) x / sphereRadius;
                    float sizeFractionY = (float) y / sphereRadius;
                    float sizeFractionZ = (float) z / sphereRadius;
                    if ((sizeFractionX * sizeFractionX) +
                            (sizeFractionY * sizeFractionY) +
                            (sizeFractionZ * sizeFractionZ) <= 1) {
                        blocks.add(source.offset(x, y, z));
                    }
                }
            }
        }

        this.hazardZones.put(source, new HazardZone(blocks, canSpread, trigger, condition));
        this.setDirty();
    }

    public void addCuboidZone(BlockPos source, int sizeX, int sizeY, int sizeZ, boolean canSpread,
                              HazardProperty.HazardTrigger trigger, MedicalCondition condition) {
        if (expandHazard(source, sizeX * sizeY * sizeZ / 100)) {
            return;
        }

        Set<BlockPos> blocks = new HashSet<>();
        sizeX = sizeX / 2;
        sizeY = sizeY / 2;
        sizeZ = sizeZ / 2;
        for (int x = -sizeX; x < sizeX; x++) {
            for (int y = -sizeY; y < sizeY; y++) {
                for (int z = -sizeZ; z < sizeZ; z++) {
                    blocks.add(source.offset(x, y, z));
                }
            }
        }

        this.hazardZones.put(source, new HazardZone(blocks, canSpread, trigger, condition));
        this.setDirty();
    }

    public void addCuboidZone(BlockPos source, int size, boolean canSpread,
                              HazardProperty.HazardTrigger trigger, MedicalCondition condition) {
        if (expandHazard(source, size * size * size / 100)) {
            return;
        }

        Set<BlockPos> blocks = new HashSet<>();
        size = size / 2;
        for (int x = -size; x < size; x++) {
            for (int y = -size; y < size; y++) {
                for (int z = -size; z < size; z++) {
                    blocks.add(source.offset(x, y, z));
                }
            }
        }

        this.hazardZones.put(source, new HazardZone(blocks, canSpread, trigger, condition));
        this.setDirty();
    }

    public void addCuboidZone(BlockPos source, BlockPos start, BlockPos end, boolean canSpread,
                              HazardProperty.HazardTrigger trigger, MedicalCondition condition) {
        int sizeX = start.getX() - end.getX();
        int sizeY = start.getY() - end.getY();
        int sizeZ = start.getZ() - end.getZ();
        if (expandHazard(source, Math.abs(sizeX * sizeY * sizeZ) / 100)) {
            return;
        }

        Set<BlockPos> blocks = new HashSet<>();
        for (BlockPos pos : BlockPos.betweenClosed(start, end)) {
            blocks.add(pos.immutable());
        }
        this.hazardZones.put(source, new HazardZone(blocks, canSpread, trigger, condition));
        this.setDirty();
    }

    @NotNull
    @Override
    public CompoundTag save(@NotNull CompoundTag compoundTag) {
        ListTag hazardZonesTag = new ListTag();
        for (var entry : hazardZones.entrySet()) {
            CompoundTag zoneTag = new CompoundTag();

            zoneTag.putLong("pos", entry.getKey().asLong());
            entry.getValue().serializeNBT(zoneTag);

            hazardZonesTag.add(zoneTag);
        }
        compoundTag.put("zones", hazardZonesTag);
        return compoundTag;
    }

    public record HazardZone(Set<BlockPos> blocks, boolean canSpread,
                             HazardProperty.HazardTrigger trigger, MedicalCondition condition) {

        public int strength() {
            return blocks.size();
        }

        public CompoundTag serializeNBT(CompoundTag zoneTag) {
            ListTag blocksTag = new ListTag();
            blocks.stream()
                    .map(NbtUtils::writeBlockPos)
                    .forEach(blocksTag::add);
            zoneTag.put("blocks", blocksTag);
            zoneTag.putBoolean("can_spread", canSpread);
            zoneTag.putString("trigger", trigger.name());
            zoneTag.putString("condition", condition.id.toString());

            return zoneTag;
        }

        public static HazardZone deserializeNBT(CompoundTag zoneTag) {
            Set<BlockPos> blocks = zoneTag.getList("blocks", Tag.TAG_COMPOUND).stream()
                    .map(CompoundTag.class::cast)
                    .map(NbtUtils::readBlockPos)
                    .collect(Collectors.toSet());
            boolean canSpread = zoneTag.getBoolean("can_spread");
            HazardProperty.HazardTrigger trigger = HazardProperty.HazardTrigger.ALL_TRIGGERS
                    .get(zoneTag.getString("trigger"));

            ResourceLocation id = GTCEu.id(zoneTag.getString("condition"));
            if (!GTRegistries.MEDICAL_CONDITIONS.containsKey(id)) {
                return null;
            }
            MedicalCondition condition = GTRegistries.MEDICAL_CONDITIONS.get(id);

            return new HazardZone(blocks, canSpread, trigger, condition);
        }
    }
}

package com.gregtechceu.gtceu.common.capability;

import com.gregtechceu.gtceu.GTCEu;
import com.gregtechceu.gtceu.api.GTValues;
import com.gregtechceu.gtceu.api.capability.GTCapability;
import com.gregtechceu.gtceu.api.data.chemical.material.Material;
import com.gregtechceu.gtceu.api.data.chemical.material.properties.HazardProperty;
import com.gregtechceu.gtceu.api.data.chemical.material.properties.PropertyKey;
import com.gregtechceu.gtceu.api.data.chemical.material.stack.MaterialEntry;
import com.gregtechceu.gtceu.api.data.medicalcondition.MedicalCondition;
import com.gregtechceu.gtceu.api.data.medicalcondition.MedicalCondition.IdleProgressionType;
import com.gregtechceu.gtceu.api.data.medicalcondition.Symptom;
import com.gregtechceu.gtceu.api.data.medicalcondition.Symptom.ConfiguredSymptom;
import com.gregtechceu.gtceu.api.registry.GTRegistries;

import net.minecraft.core.Direction;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.nbt.ListTag;
import net.minecraft.nbt.StringTag;
import net.minecraft.nbt.Tag;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.util.Mth;
import net.minecraft.world.effect.MobEffect;
import net.minecraft.world.effect.MobEffectInstance;
import net.minecraft.world.entity.player.Player;
import net.minecraftforge.common.capabilities.Capability;
import net.minecraftforge.common.capabilities.ICapabilitySerializable;
import net.minecraftforge.common.util.LazyOptional;

import it.unimi.dsi.fastutil.objects.*;
import lombok.Getter;
import org.jetbrains.annotations.NotNull;
import org.jetbrains.annotations.Nullable;
import org.jetbrains.annotations.VisibleForTesting;

import java.util.*;

public class MedicalConditionTracker implements ICapabilitySerializable<CompoundTag> {

    @Getter
    @VisibleForTesting
    final Reference2FloatOpenHashMap<MedicalCondition> medicalConditions = new Reference2FloatOpenHashMap<>();
    private final Set<MedicalCondition> permanentConditions = new ReferenceOpenHashSet<>();
    @Getter
    private final Object2IntMap<ConfiguredSymptom> activeSymptoms = new Object2IntOpenHashMap<>();
    private final Reference2IntMap<MobEffect> activeMobEffects = new Reference2IntOpenHashMap<>();

    private final Set<MedicalCondition> flaggedForRemoval = new ReferenceOpenHashSet<>();

    @Getter
    private final Player player;

    private final LazyOptional<MedicalConditionTracker> holder = LazyOptional.of(() -> this);

    public MedicalConditionTracker(Player player) {
        this.player = player;
    }

    public void tick() {
        if (player.isCreative()) return;

        for (var entry : activeMobEffects.reference2IntEntrySet()) {
            player.addEffect(new MobEffectInstance(entry.getKey(), 100, entry.getIntValue()));
        }

        for (MedicalCondition condition : medicalConditions.keySet()) {
            if (condition.idleProgressionType == IdleProgressionType.NONE ||
                    condition.idleProgressionRate == 0.0f) {
                continue;
            }
            if (permanentConditions.contains(condition) &&
                    condition.idleProgressionType == IdleProgressionType.HEAL) {
                // can't automatically heal permanent conditions.
                continue;
            }
            int multiplier = (condition.idleProgressionType == IdleProgressionType.HEAL) ? -1 : 1;
            medicalConditions.addTo(condition, condition.idleProgressionRate * multiplier);
            evaluateMedicalCondition(condition);
        }
        if (!medicalConditions.isEmpty()) {
            updateActiveSymptoms();
        }
    }

    public void progressRelatedCondition(@NotNull Material material, int count) {
        HazardProperty materialHazard = material.getProperty(PropertyKey.HAZARD);
        float strength = (float) count * materialHazard.progressionMultiplier;
        progressCondition(materialHazard.condition, strength);
    }

    public void progressRelatedCondition(@NotNull MaterialEntry materialEntry, int count) {
        HazardProperty materialHazard = materialEntry.material().getProperty(PropertyKey.HAZARD);
        float strength = (float) (materialEntry.getMaterialAmount() / GTValues.M) * count *
                materialHazard.progressionMultiplier;
        progressCondition(materialHazard.condition, strength);
    }

    /**
     * Progress a condition {@code condition} by {@code progression} counts.<br>
     * This is invoked with negative values on antidote/cure consumption.
     *
     * @param condition   MedicalCondition to heal
     * @param progression amount of progression to decrease
     */
    public void progressCondition(@NotNull MedicalCondition condition, float progression) {
        // if progression is negative, remove zeroed conditions as well
        if (progression < 0.0f && -progression >= medicalConditions.getFloat(condition)) {
            removeMedicalCondition(condition);
        } else {
            if (player.isCreative()) return;

            medicalConditions.addTo(condition, progression);
        }
        updateActiveSymptoms();
    }

    public void removeMedicalCondition(MedicalCondition condition) {
        flaggedForRemoval.add(condition);
        permanentConditions.remove(condition);
    }

    @VisibleForTesting
    void updateActiveSymptoms() {
        for (MedicalCondition condition : medicalConditions.keySet()) {
            if (flaggedForRemoval.contains(condition)) {
                continue;
            }
            if (medicalConditions.getFloat(condition) >= condition.maxProgression * 2) {
                // If condition has been applied for 2x the maximum time, make it permanent.
                permanentConditions.add(condition);
            }

            for (ConfiguredSymptom configured : condition.symptoms) {
                int stage = Math.max(calculateStage(condition, configured), 0);
                Symptom symptom = configured.getSymptom();
                symptom.tick(this, condition, configured, stage);

                Optional<ConfiguredSymptom> maybeExisting = activeSymptoms.keySet()
                        .stream()
                        .filter(s -> s.getSymptom() == symptom)
                        .findFirst();
                if (maybeExisting.isEmpty() || maybeExisting.get() == configured) {
                    if (stage == 0) {
                        activeSymptoms.removeInt(configured);
                    } else {
                        activeSymptoms.put(configured, stage);
                    }

                    symptom.applyProgression(this, condition, configured, stage);
                    continue;
                }
                if (stage == 0) {
                    // if stage == 0, the last check can't ever be true. In that case, just skip it.
                    continue;
                }

                ConfiguredSymptom existing = maybeExisting.get();
                int existingStage = activeSymptoms.getInt(existing);
                if (configured.getRelativeHarshness() * stage > existing.getRelativeHarshness() * existingStage) {
                    activeSymptoms.removeInt(existing);
                    activeSymptoms.put(configured, stage);

                    symptom.applyProgression(this, condition, configured, stage);
                    continue;
                }
            }
        }

        if (flaggedForRemoval.isEmpty()) {
            return;
        }
        for (MedicalCondition condition : flaggedForRemoval) {
            Set<ConfiguredSymptom> toRemove = new HashSet<>();
            activeSymptoms.keySet().stream()
                    .filter(condition.symptoms::contains)
                    .forEach(symptom -> {
                        // reset all symptom effects for this condition
                        symptom.getSymptom().applyProgression(this, condition, symptom, 0);
                        toRemove.add(symptom);
                    });
            for (ConfiguredSymptom symptom : toRemove) {
                activeSymptoms.removeInt(symptom);
            }

            medicalConditions.removeFloat(condition);
        }
        flaggedForRemoval.clear();
    }

    private int calculateStage(MedicalCondition condition, ConfiguredSymptom symptom) {
        float minThreshold = symptom.getMinThreshold();
        float maxThreshold = symptom.getMaxThreshold();
        float progression = medicalConditions.getFloat(condition);

        if (progression < minThreshold) {
            return 0;
        }
        if (progression >= maxThreshold) {
            return symptom.getStages();
        }
        float delta = Mth.inverseLerp(Math.min(progression, condition.maxProgression), minThreshold, maxThreshold);
        return (int) (delta * symptom.getStages());
    }

    // removes MedicalConditions without progression
    private void evaluateMedicalCondition(MedicalCondition condition) {
        if (permanentConditions.contains(condition)) {
            return;
        }
        if (medicalConditions.getFloat(condition) <= 0) {
            removeMedicalCondition(condition);
        }
    }

    public void setMobEffect(MobEffect effect, int amplifier) {
        if (amplifier <= 0) {
            activeMobEffects.removeInt(effect);
            return;
        }
        activeMobEffects.mergeInt(effect, amplifier, Math::max);
    }

    @Override
    public CompoundTag serializeNBT() {
        CompoundTag tag = new CompoundTag();

        ListTag effectsTag = new ListTag();
        for (var entry : medicalConditions.reference2FloatEntrySet()) {
            CompoundTag medicalConditionTag = new CompoundTag();
            medicalConditionTag.putString("condition", entry.getKey().id.toString());
            medicalConditionTag.putFloat("progression", entry.getFloatValue());
            effectsTag.add(medicalConditionTag);
        }
        tag.put("medical_conditions", effectsTag);

        ListTag permanentsTag = new ListTag();
        for (MedicalCondition condition : permanentConditions) {
            permanentsTag.add(StringTag.valueOf(condition.id.toString()));
        }
        tag.put("permanent_conditions", permanentsTag);

        return tag;
    }

    @Override
    public void deserializeNBT(CompoundTag arg) {
        // ensure the medical condition map(s) is actually empty before loading.
        // IDK if this actually happens, but better be safe than sorry.
        medicalConditions.clear();
        permanentConditions.clear();

        ListTag medicalConditionsTag = arg.getList("medical_conditions", Tag.TAG_COMPOUND);
        for (int i = 0; i < medicalConditionsTag.size(); ++i) {
            CompoundTag compoundTag = medicalConditionsTag.getCompound(i);
            ResourceLocation id = GTCEu.id(compoundTag.getString("condition"));
            if (!GTRegistries.MEDICAL_CONDITIONS.containsKey(id)) {
                continue;
            }
            MedicalCondition condition = GTRegistries.MEDICAL_CONDITIONS.get(id);
            float progression = compoundTag.getFloat("progression");

            medicalConditions.put(condition, progression);
        }

        ListTag permanentConditionsTag = arg.getList("permanent_conditions", Tag.TAG_STRING);
        for (int i = 0; i < permanentConditionsTag.size(); ++i) {
            ResourceLocation id = GTCEu.id(permanentConditionsTag.getString(i));
            if (!GTRegistries.MEDICAL_CONDITIONS.containsKey(id)) {
                continue;
            }
            permanentConditions.add(GTRegistries.MEDICAL_CONDITIONS.get(id));
        }
    }

    @Override
    public @NotNull <T> LazyOptional<T> getCapability(@NotNull Capability<T> cap, @Nullable Direction side) {
        return GTCapability.CAPABILITY_MEDICAL_CONDITION_TRACKER.orEmpty(cap, this.holder);
    }
}

package com.gregtechceu.gtceu.common.commands;

import com.gregtechceu.gtceu.api.data.chemical.material.properties.HazardProperty;
import com.gregtechceu.gtceu.api.data.medicalcondition.MedicalCondition;
import com.gregtechceu.gtceu.common.capability.EnvironmentalHazardSavedData;
import com.gregtechceu.gtceu.common.capability.LocalizedHazardSavedData;
import com.gregtechceu.gtceu.common.commands.arguments.MedicalConditionArgument;

import net.minecraft.commands.CommandBuildContext;
import net.minecraft.commands.CommandSourceStack;
import net.minecraft.commands.Commands;
import net.minecraft.commands.arguments.coordinates.BlockPosArgument;
import net.minecraft.core.BlockPos;
import net.minecraft.server.level.ServerLevel;

import com.mojang.brigadier.CommandDispatcher;
import com.mojang.brigadier.arguments.BoolArgumentType;
import com.mojang.brigadier.arguments.IntegerArgumentType;
import com.mojang.brigadier.context.CommandContext;

import static net.minecraft.commands.Commands.*;

public class HazardCommands {

    // spotless:off
    public static void register(CommandDispatcher<CommandSourceStack> dispatcher, CommandBuildContext buildContext) {
        dispatcher.register(
                literal("environmental_hazard")
                        .requires(source -> source.hasPermission(LEVEL_ADMINS))
                        .then(argument("condition", MedicalConditionArgument.medicalCondition())
                                .then(argument("can_spread", BoolArgumentType.bool())
                                        .then(argument("source", BlockPosArgument.blockPos())
                                                .then(literal("chunk")
                                                        .then(Commands.argument("strength", IntegerArgumentType.integer(1))
                                                                .executes(HazardCommands::spawnChunkEnvironmentalHazard)))
                                                .then(literal("local")
                                                        .then(Commands.argument("from", BlockPosArgument.blockPos())
                                                                .then(Commands.argument("to", BlockPosArgument.blockPos())
                                                                        .executes(HazardCommands::spawnLocalEnvironmentalHazard)))))))
                        .then(literal("clear")
                                .then(argument("source", BlockPosArgument.blockPos())
                                        .executes(context -> {
                                            BlockPos source = BlockPosArgument.getBlockPos(context, "source");
                                            return clearEnvironmentalHazard(context, source, null);
                                        })
                                        .then(argument("condition", MedicalConditionArgument.medicalCondition())
                                                .executes(context -> {
                                                    BlockPos source = BlockPosArgument.getBlockPos(context, "source");
                                                    MedicalCondition condition = MedicalConditionArgument.getCondition(context, "condition");
                                                    return clearEnvironmentalHazard(context, source, condition);
                                                })))));
    }
    // spotless:on

    private static int spawnChunkEnvironmentalHazard(CommandContext<CommandSourceStack> context) {
        ServerLevel serverLevel = context.getSource().getLevel();

        BlockPos source = BlockPosArgument.getBlockPos(context, "source");
        int strength = IntegerArgumentType.getInteger(context, "strength");
        MedicalCondition condition = MedicalConditionArgument.getCondition(context, "condition");
        boolean canSpread = BoolArgumentType.getBool(context, "can_spread");

        EnvironmentalHazardSavedData.getOrCreate(serverLevel)
                .addZone(source, strength, canSpread, HazardProperty.HazardTrigger.INHALATION, condition);

        return 1;
    }

    private static int spawnLocalEnvironmentalHazard(CommandContext<CommandSourceStack> context) {
        ServerLevel serverLevel = context.getSource().getLevel();
        BlockPos source = BlockPosArgument.getBlockPos(context, "source");
        BlockPos from = BlockPosArgument.getBlockPos(context, "from");
        BlockPos to = BlockPosArgument.getBlockPos(context, "to");

        MedicalCondition condition = MedicalConditionArgument.getCondition(context, "condition");
        boolean canSpread = BoolArgumentType.getBool(context, "can_spread");

        LocalizedHazardSavedData.getOrCreate(serverLevel)
                .addCuboidZone(source, from, to, canSpread, HazardProperty.HazardTrigger.INHALATION, condition);

        return 1;
    }

    private static int clearEnvironmentalHazard(CommandContext<CommandSourceStack> context,
                                                BlockPos clearAt, MedicalCondition condition) {
        ServerLevel serverLevel = context.getSource().getLevel();
        if (condition == null) {
            EnvironmentalHazardSavedData.getOrCreate(serverLevel).removeZone(clearAt);
            LocalizedHazardSavedData.getOrCreate(serverLevel).removeZoneByPosition(clearAt);
        } else {
            EnvironmentalHazardSavedData.getOrCreate(serverLevel).removeZone(clearAt, condition);
            LocalizedHazardSavedData.getOrCreate(serverLevel).removeZoneByPosition(clearAt, condition);
        }
        return 1;
    }
}

package com.gregtechceu.gtceu.common.machine.trait.hazard;

import com.gregtechceu.gtceu.api.capability.GTCapabilityHelper;
import com.gregtechceu.gtceu.api.capability.IHazardParticleContainer;
import com.gregtechceu.gtceu.api.data.chemical.material.properties.HazardProperty;
import com.gregtechceu.gtceu.api.data.medicalcondition.MedicalCondition;
import com.gregtechceu.gtceu.api.machine.trait.MachineTrait;
import com.gregtechceu.gtceu.common.capability.LocalizedHazardSavedData;
import com.gregtechceu.gtceu.config.ConfigHolder;

import net.minecraft.server.level.ServerLevel;

import lombok.Getter;
import lombok.Setter;

/**
 * trait for localized hazard (e.g. radiation) emitters like nuclear reactors.
 */
public class LocalizedHazardEmitterTrait extends MachineTrait {

    @Getter
    @Setter
    private MedicalCondition conditionToEmit;
    @Getter
    @Setter
    private int conditionStrength;

    public LocalizedHazardEmitterTrait(MedicalCondition conditionToEmit,
                                       int defaultConditionStrength) {
        super();
        this.conditionToEmit = conditionToEmit;
        this.conditionStrength = defaultConditionStrength;
    }

    public void spreadHazard() {
        if (!ConfigHolder.INSTANCE.gameplay.environmentalHazards) {
            return;
        }

        if (getLevel() instanceof ServerLevel serverLevel) {
            IHazardParticleContainer container = GTCapabilityHelper.getHazardContainer(serverLevel,
                    getBlockPos().relative(getMachine().getFrontFacing()), getMachine().getFrontFacing().getOpposite());
            if (container != null &&
                    container.getHazardCanBeInserted(getConditionToEmit()) > getConditionStrength()) {
                container.addHazard(getConditionToEmit(), getConditionStrength());
                return;
            }

            var savedData = LocalizedHazardSavedData.getOrCreate(serverLevel);
            savedData.addSphericalZone(getBlockPos(), getConditionStrength(), false,
                    HazardProperty.HazardTrigger.INHALATION, getConditionToEmit());
        }
    }
}
